import {useEffect,useLayoutEffect,useRef,useState,type ReactNode} from 'react';
import {ArrowLeftIcon,ChevronRightIcon,Cross2Icon,HeartIcon,HeartFilledIcon,StarIcon,StarFilledIcon,ChatBubbleIcon,DotsHorizontalIcon,CheckIcon,Pencil1Icon,ReaderIcon,MagnifyingGlassIcon,ExternalLinkIcon,ArrowDownIcon,ArrowUpIcon,CopyIcon,Share1Icon,ResetIcon,SpeakerLoudIcon,CameraIcon,PlusCircledIcon,ColorWheelIcon,MagicWandIcon,MixIcon,MinusCircledIcon,PlusIcon,CircleIcon,ChevronLeftIcon} from '@radix-ui/react-icons';
import {BottomSheet,KeyboardInput,KeyboardTextarea,useKeyboard,useKeyboardInsets} from './mobile';
import {AS,notes,cards,sources,sections,sectionsFor,queries,type Evidence,type Fact,type Note,type Candidate} from './data';

import {aiCandidates,answerRefs,respondToBeauty,commentRef,imageRef,type AiCandidate,type Followup} from './ai-content';

import {taskExtras,planLabel,planIntro,orderedPlans,visibleUpdates,type TaskQuestion} from './task-content';

import {ContentImage} from './ContentImage';
import {FeedbackPhotoPicker,FeedbackPhotos} from './FeedbackPhotos';
import {saveFeedbackPhotos,deleteFeedbackPhotos,type FeedbackPhoto,type PreparedPhoto} from './feedback-photos';
import {AppScroll as MobileScroll, AppCarousel as Carousel, useNativeViewport} from './AppScroll';
import {sceneForQuery,sceneForNote,sceneForId,respondToScene} from './scene-content';
import {UserName,UserMentions} from './user-mentions';

type LocalQuestion={id:string;noteId:string;candidateIds?:string[];candidateId?:string;title:string;date:string};
type LocalAnswer={id:string;noteId:string;questionId:string;text:string;date:string};
type ChatSession={query:string;followups:Followup[]};
type Page='chat'|'home'|'results'|'search'|'note'|'ai';
type Sheet='task'|'sources'|'feedback'|'menu'|'creator'|'ask'|'question'|null;
type Feedback={id:string;noteId:string;candidateId:string;candidateName:string;text:string;skin:string;result:string;date:string;photos?:FeedbackPhoto[]};
type Saved={collected:string[];liked:string[];followed:string[];choices?:Record<string,string>;tried:string[];feedback:Feedback[];mounted:Record<string,boolean>;titles:Record<string,string>;answerSaved?:boolean;savedSummaries?:string[];chats?:ChatSession[];questions:LocalQuestion[];answers:LocalAnswer[];alsoAsked:string[]};
const initial:Saved={collected:[],liked:[],followed:[],choices:{},tried:[],feedback:[],mounted:{},titles:{},questions:[],answers:[],alsoAsked:[]};
const storageKey=new URLSearchParams(location.search).get('qa')==='1'?'xhs-qa-session':'xhs-beauty-v2';
const authorMode=new URLSearchParams(location.search).get('mode')==='author';
const initialQuery=sceneForId(new URLSearchParams(location.search).get('scene')||'beauty').query;
const toolsMode=new URLSearchParams(location.search).get('tools')==='1';
function load():Saved{try{const value=JSON.parse(localStorage.getItem(storageKey)||'null');if(!value)return initial;for(const k of ['collected','liked','followed','tried','feedback'])if(!Array.isArray(value[k]))return initial;return {...initial,...value}}catch{return initial}}
function displayCount(value:string,delta=0){const n=Number(value);return Number.isFinite(n)?String(n+delta):value;}
function Avatar({name,small=false}:{name:string;small?:boolean}){return <span className={'avatar '+(small?'small':'')}>{Array.from(name)[0]}</span>}
function Icon({label,children,onClick,disabled=false}:{label:string;children:ReactNode;onClick:()=>void;disabled?:boolean}){return <button type="button" className="icon-button" aria-label={label} disabled={disabled} onClick={disabled?undefined:onClick}>{children}</button>}
function getCard(id:string){return cards.find(c=>c.noteId===id)!}
function getNote(id:string){return notes.find(n=>n.id===id)!}

export default function Prototype(){
 const [saved,setSaved]=useState<Saved>(load);
 const [page,setPage]=useState<Page>(()=>location.hash==='#ai'?'ai':new URLSearchParams(location.search).has('scene')?'results':'home'),[origin,setOrigin]=useState<Page>('home');
 const [noteId,setNoteId]=useState(notes[0].id),[taskId,setTaskId]=useState(notes[0].id);
 const [sheet,setSheet]=useState<Sheet>(null),[sheetBack,setSheetBack]=useState<Sheet>(null);
 const sheetPositions=useRef<Record<string,number>>({});
 const pagePositions=useRef<Record<string,number>>({});
 const [questionId,setQuestionId]=useState(''),[questionDraft,setQuestionDraft]=useState(''),[questionScopes,setQuestionScopes]=useState<string[]>([]),[replyDraft,setReplyDraft]=useState('');
 const [followups,setFollowups]=useState<Followup[]>([]),[dislikedQueries,setDislikedQueries]=useState<Record<string,boolean>>({});
 const [homeLeaving,setHomeLeaving]=useState(false),[chatJump,setChatJump]=useState('');
 const chats=saved.chats||[];
 const recordChat=(chat:ChatSession)=>setSaved(s=>({...s,chats:[...(s.chats||[]).filter(c=>c.query!==chat.query),chat]}));
 const [query,setQuery]=useState(initialQuery),[input,setInput]=useState(initialQuery),[tab,setTab]=useState('全部'),[filter,setFilter]=useState('综合');
 const [selected,setSelected]=useState(''),[sourceIds,setSourceIds]=useState<string[]>([]);
 const [expanded,setExpanded]=useState<Record<string,number>>({}),[jump,setJump]=useState(''),[highlight,setHighlight]=useState('');
 const [feedbackPhotos,setFeedbackPhotos]=useState<PreparedPhoto[]>([]),[photosBusy,setPhotosBusy]=useState(false),[publishing,setPublishing]=useState(false);
 const photoDraftRef=useRef<PreparedPhoto[]>([]),publishLock=useRef(false);
 useEffect(()=>{photoDraftRef.current=feedbackPhotos},[feedbackPhotos]);
 useEffect(()=>{if(sheet!=='feedback'){photoDraftRef.current.forEach(photo=>URL.revokeObjectURL(photo.preview));setFeedbackPhotos([])}},[sheet]);
 useEffect(()=>()=>{photoDraftRef.current.forEach(photo=>URL.revokeObjectURL(photo.preview))},[]);
 const [text,setText]=useState(''),[skin,setSkin]=useState(''),[outcome,setOutcome]=useState('适合我'),[draft,setDraft]=useState(''),[toast,setToast]=useState('');
 const keyboard=useKeyboard(),{bottomInset}=useKeyboardInsets(),rootRef=useRef<HTMLDivElement>(null);
 const current=getNote(noteId),taskNote=getNote(taskId),card=getCard(taskId);
 const candidate=card.candidates.find(c=>c.id===selected);
 const choiceKey=taskId+':'+selected;
 const native=useNativeViewport();
 const titleFor=(id:string)=>saved.titles[id]||getCard(id).title;
 const mounted=(id:string)=>saved.mounted[id]!==false;
 const open=(s:Sheet)=>{keyboard.hide();if(sheet)sheetPositions.current[sheet]=document.querySelector('.sheet-content')?.scrollTop||0;setSheet(s)};
 const go=(p:Page,answerQuery=query)=>{keyboard.hide();pagePositions.current[page]=rootRef.current?.querySelector('.mobile-scroll')?.scrollTop||0;setSheet(null);if(p==='ai'){const past=chats.find(c=>c.query===answerQuery);const turns=past?.followups||(answerQuery===query?followups:[]);setFollowups(turns);if(answerQuery!==query){setQuery(answerQuery);setInput(answerQuery)}recordChat({query:answerQuery,followups:turns})}setPage(p)};
 useEffect(()=>{if(page==='ai'&&!chats.some(c=>c.query===query))recordChat({query,followups})},[page,query]);
 const openChat=()=>{setHomeLeaving(true);setChatJump('guide');go('chat')};
 useLayoutEffect(()=>{if(homeLeaving){const scroll=rootRef.current?.querySelector('.home-slide-away .mobile-scroll');if(scroll)scroll.scrollTop=pagePositions.current.home||0}},[homeLeaving]);
 useEffect(()=>{if(!homeLeaving)return;const timer=setTimeout(()=>setHomeLeaving(false),380);return()=>clearTimeout(timer)},[homeLeaving]);
 useEffect(()=>{if(page!=='chat'||!chatJump)return;const frame=requestAnimationFrame(()=>{const scroll=rootRef.current?.querySelector('.chat-screen .mobile-scroll');const target=chatJump==='guide'?rootRef.current?.querySelector('.chat-guide'):Array.from(rootRef.current?.querySelectorAll<HTMLElement>('[data-chat-query]')||[]).find(el=>el.dataset.chatQuery===chatJump);if(scroll&&target)scroll.scrollTop+=target.getBoundingClientRect().top-scroll.getBoundingClientRect().top-(chatJump==='guide'?190:12);setChatJump('')});return()=>cancelAnimationFrame(frame)},[page,chatJump,chats.length]);
 const beginSearch=()=>{setInput('');go('search')};
 const toggle=(field:'collected'|'liked'|'followed'|'tried',key:string)=>setSaved(s=>({...s,[field]:s[field].includes(key)?s[field].filter(x=>x!==key):[...s[field],key]}));
 const openNote=(id:string,target='')=>{
  if(page!=='note')setOrigin(page);
  setNoteId(id);go('note');setJump(target||'note-start');setHighlight(target);
  const source=sources[target];if(source?.parent){const replies=getNote(id).comments.filter(c=>c.parent===source.parent);const index=replies.findIndex(c=>c.id===target);if(index>=0)setExpanded(v=>({...v,[source.parent!]:Math.max(v[source.parent!]||0,Math.min(replies.length,Math.ceil((index+1)/5)*5))}));}
 };
 const lastTried=(id:string)=>saved.tried.filter(key=>key.startsWith(id+':')).at(-1)?.slice(id.length+1);
 const triedPlans=cards.flatMap(c=>c.candidates.filter(item=>saved.tried.includes(c.noteId+':'+item.id)).map(item=>({noteId:c.noteId,...item})));
 const openTask=(id:string,item?:string)=>{
  if(!mounted(id)){setToast('这份作业暂时无法查看');return;}sheetPositions.current.task=0;setTaskId(id);const stored=lastTried(id);setSelected(item||(stored&&getCard(id).candidates.some(c=>c.id===stored)?stored:orderedPlans(id)[0].id));open('task');
 };
 const showSources=(ids:string[])=>{sheetPositions.current.sources=0;setSourceIds([...new Set(ids)]);setSheetBack(sheet==='task'||sheet==='question'?sheet:null);open('sources')};
 const search=(value:string)=>{if(!value.trim())return;setQuery(value.trim());setInput(value.trim());setFilter('综合');setTab('全部');setFollowups([]);pagePositions.current.ai=0;pagePositions.current.results=0;setDislikedQueries({});go('results')};
 const startFeedback=()=>{if(!candidate)return;sheetPositions.current.feedback=0;setText('');setSkin('');setOutcome('适合我');open('feedback')};
 const publish=async()=>{
  if(!text.trim()||!candidate||photosBusy||publishLock.current)return;
  publishLock.current=true;setPublishing(true);keyboard.hide();
  const photos=feedbackPhotos.map(({id,width,height})=>({id,width,height}));
  const f:Feedback={id:'feedback-'+Date.now(),noteId:taskId,candidateId:candidate.id,candidateName:candidate.name,text:text.trim(),skin:skin.trim(),result:outcome,date:new Date().toLocaleDateString('zh-CN'),...(photos.length?{photos}:{})};
  try{await saveFeedbackPhotos(feedbackPhotos);const next={...saved,feedback:[f,...saved.feedback]};localStorage.setItem(storageKey,JSON.stringify(next));setSaved(next);open('task');setToast('已发布到原笔记评论区')}
  catch{await deleteFeedbackPhotos(photos).catch(()=>{});setToast('保存失败，请检查存储空间后重试')}
  finally{publishLock.current=false;setPublishing(false)}
 };
 const deleteFeedback=(id:string)=>{const removed=saved.feedback.find(f=>f.id===id);const next={...saved,feedback:saved.feedback.filter(f=>f.id!==id)};try{localStorage.setItem(storageKey,JSON.stringify(next));setSaved(next);void deleteFeedbackPhotos(removed?.photos||[]).catch(()=>{});setToast('反馈已删除')}catch{setToast('删除失败，请重试')}};
 useEffect(()=>{try{localStorage.setItem(storageKey,JSON.stringify(saved))}catch{setToast('保存失败，请检查浏览器存储空间')}},[saved]);
 useEffect(()=>{if(!toast)return;const id=setTimeout(()=>setToast(''),2600);return()=>clearTimeout(id)},[toast]);
 useEffect(()=>{const update=()=>document.documentElement.style.setProperty('--real-vh',`${window.visualViewport?.height||innerHeight}px`);update();window.visualViewport?.addEventListener('resize',update);return()=>window.visualViewport?.removeEventListener('resize',update)},[]);
 useEffect(()=>{document.documentElement.style.setProperty('--sheet-snap',sheet==='task'?'.9':'.82');const content=document.querySelector('.sheet-content');if(content)content.scrollTop=sheet?(sheetPositions.current[sheet]||0):0},[sheet,taskId]);
 useEffect(()=>{if(page!=='note'||!jump)return;const frame=requestAnimationFrame(()=>{const target=rootRef.current?.querySelector(`[data-anchor="${jump}"]`);const scroll=target?.closest('.mobile-scroll');if(target&&scroll){scroll.scrollTop+=target.getBoundingClientRect().top-scroll.getBoundingClientRect().top-12}setJump('')});return()=>cancelAnimationFrame(frame)},[page,noteId,jump,expanded]);
 useEffect(()=>{
  if(page==='note'||(page==='chat'&&chatJump))return;
  const frame=requestAnimationFrame(()=>{const scroll=rootRef.current?.querySelector('.mobile-scroll');if(scroll)scroll.scrollTop=pagePositions.current[page]||0});
  return()=>cancelAnimationFrame(frame);
 },[page]);
 useEffect(()=>{
  if(sheet!=='task')return;
  const frame=requestAnimationFrame(()=>{const tab=document.querySelector<HTMLElement>('.plan-tab[aria-selected="true"]');const rail=tab?.closest('.mobile-carousel');if(tab&&rail){const t=tab.getBoundingClientRect(),r=rail.getBoundingClientRect();if(t.left<r.left||t.right>r.right)rail.scrollLeft+=t.left-r.left-12}});
  return()=>cancelAnimationFrame(frame);
 },[sheet,taskId,selected]);
 const switchPlan=(id:string)=>{keyboard.hide();setSelected(id);const nav=document.querySelector('.plan-nav'),scroll=nav?.closest('.sheet-content');if(nav&&scroll&&nav.getBoundingClientRect().top<scroll.getBoundingClientRect().top)scroll.scrollTop+=nav.getBoundingClientRect().top-scroll.getBoundingClientRect().top};
 const extras=taskExtras[taskId];
 const questions:(TaskQuestion|LocalQuestion)[]=[...saved.questions.filter(q=>q.noteId===taskId),...(extras.questions||[])];
 const activeQuestion=questions.find(q=>q.id===questionId);
 const startQuestion=()=>{setQuestionDraft('');setQuestionScopes(selected?[selected]:[]);sheetPositions.current.ask=0;open('ask')};
 const showQuestion=(id:string)=>{setQuestionId(id);setReplyDraft('');sheetPositions.current.question=0;open('question')};
 const publishQuestion=()=>{if(!questionDraft.trim()||!questionScopes.length)return;const q:LocalQuestion={id:'question-'+Date.now(),noteId:taskId,candidateIds:orderedPlans(taskId).filter(c=>questionScopes.includes(c.id)).map(c=>c.id),title:questionDraft.trim(),date:new Date().toLocaleDateString('zh-CN')};setSaved(s=>({...s,questions:[q,...s.questions]}));setQuestionId(q.id);setQuestionDraft('');setReplyDraft('');sheetPositions.current.question=0;open('question');setToast('提问已发布')};
 const publishAnswer=()=>{if(!replyDraft.trim()||!activeQuestion)return;const a:LocalAnswer={id:'answer-'+Date.now(),noteId:taskId,questionId:activeQuestion.id,text:replyDraft.trim(),date:new Date().toLocaleDateString('zh-CN')};setSaved(s=>({...s,answers:[...s.answers,a]}));setReplyDraft('');keyboard.hide();setToast('回答已发布')};
 const alsoAsk=(id:string)=>setSaved(s=>({...s,alsoAsked:s.alsoAsked.includes(id)?s.alsoAsked.filter(x=>x!==id):[...s.alsoAsked,id]}));
 const deleteQuestion=(id:string)=>{setSaved(s=>({...s,questions:s.questions.filter(q=>q.id!==id),answers:s.answers.filter(a=>a.questionId!==id),alsoAsked:s.alsoAsked.filter(x=>x!==id)}));open('task');setToast('提问已删除')};
 const scrollAi=(end=false)=>{keyboard.hide();const scroll=rootRef.current?.querySelector('.ai-screen .mobile-scroll');scroll?.scrollTo({top:end?scroll.scrollHeight:0,behavior:'smooth'})};
 const askFollowup=(question:string)=>{
  if(!question.trim())return;keyboard.hide();const answer=scene?(scene.id!=='beauty'?respondToScene(scene,question.trim()):respondToBeauty(question.trim())):{question:question.trim(),answer:'暂时没有找到相关笔记，可以换个关键词再看看。',refs:[]};const turns=[...followups,answer];setFollowups(turns);recordChat({query,followups:turns});
 };
 const askChat=(question:string)=>{const q=question.trim();if(!q)return;keyboard.hide();const matched=sceneForQuery(q);const last=chats.at(-1);if(!matched&&last&&sceneForQuery(last.query)){const priorScene=sceneForQuery(last.query)!;const answer=priorScene.id==='beauty'?respondToBeauty(q):respondToScene(priorScene,q);recordChat({...last,followups:[...last.followups,answer]});setChatJump('guide')}else{recordChat({query:q,followups:chats.find(c=>c.query===q)?.followups||[]});setChatJump(q)}};
 useEffect(()=>{if(page==='ai'&&followups.length){const frame=requestAnimationFrame(()=>{const scroll=rootRef.current?.querySelector('.ai-screen .mobile-scroll');const last=rootRef.current?.querySelector('.followup-turn:last-child');if(scroll&&last)scroll.scrollTop+=last.getBoundingClientRect().top-scroll.getBoundingClientRect().top-10});return()=>cancelAnimationFrame(frame)}},[followups]);
 const copyAnswer=async(answerQuery=query)=>{const content=Array.from(rootRef.current?.querySelectorAll<HTMLElement>('.main-answer')||[]).find(el=>el.dataset.answerQuery===answerQuery)?.textContent||'';try{await navigator.clipboard.writeText(content);setToast('已复制总结')}catch{setToast('复制失败，请稍后重试')}};
 const shareAnswer=async(answerQuery=query)=>{const url=location.origin+location.pathname+'?scene='+(sceneForQuery(answerQuery)?.id||'beauty')+'#ai';try{if(navigator.share)await navigator.share({title:answerQuery,text:answerQuery+'：两篇笔记与评论中的作业方案',url});else{await navigator.clipboard.writeText(url);setToast('总结链接已复制')}}catch(error){if((error as Error).name!=='AbortError')setToast('暂时无法分享，请稍后重试')}};
 const scene=sceneForQuery(query);
 const relevant=!!scene;
 const savedSummaries=saved.savedSummaries|| (saved.answerSaved?['beauty']:[]);
 const sceneNotes=notes.filter(n=>scene?.noteIds.includes(n.id));
 let results=sceneNotes;
 if(scene?.id==='beauty'){
  if(/花知晓/.test(query)||filter==='花知晓')results=results.filter(n=>n.id==='beauty_02');
  if(/3ce|裸砂|芋泥/i.test(query)||filter==='3CE')results=results.filter(n=>n.id==='beauty_01');
 }else if(scene&&filter!=='综合'){const i=scene.filters.indexOf(filter)-1;results=results.filter(n=>n.id===scene.noteIds[i]);}
 const feedbackFor=(id:string,item?:string)=>saved.feedback.filter(f=>f.noteId===id&&(!item||f.candidateId===item));
 const allRefs=(id:string)=>{const card=getCard(id),extra=taskExtras[id];return [...new Set([...(extra?.notices||[]).flatMap(f=>f.refs),...(extra?.discussions||[]).flatMap(f=>f.refs),...(extra?.questions||[]).flatMap(q=>[q.questionRef,...q.answerRefs]),...visibleUpdates(id).flatMap(u=>u.refs),...(card.context||[]).flatMap(f=>f.refs),...card.candidates.flatMap(c=>[...(c.nameRefs||[]),...sections.flatMap(s=>(c[s.key]||[]).flatMap(f=>f.refs))])])];};
 const refs=(ids:string[])=> <button className="citation" aria-label="查看这条内容的来源" onClick={()=>showSources(ids)}>来源 {ids.length}<ChevronRightIcon/></button>;
 const factList=(facts:Fact[])=><div className="fact-list">{facts.map((f,i)=><div className="fact" key={i}><p><UserMentions text={f.text} refs={f.refs}/></p>{refs(f.refs)}</div>)}</div>;
 const preview=(id:string)=>mounted(id)?<button className="task-preview" onClick={()=>openTask(id)}><span className="task-icon"><ReaderIcon/></span><span><b>{titleFor(id)}</b><small>{getCard(id).candidates.length} 个方案 · 查看做法与不同体验</small>{lastTried(id)&&<small className="choice-resume">已抄 {getCard(id).candidates.find(c=>c.id===lastTried(id))?.name}</small>}</span><ChevronRightIcon/></button>:null;
 const feedback=(f:Feedback,link=false)=><div className="comment feedback-comment" key={f.id} data-anchor={f.id}><Avatar name="我"/><div><div className="comment-name">我 <span className="tiny-tag">作业反馈</span></div><button className="feedback-choice" onClick={()=>openTask(f.noteId,f.candidateId)}>{f.candidateName}<ChevronRightIcon/></button><p>{f.text}</p><FeedbackPhotos photos={f.photos}/><div className="comment-meta">{[f.skin,f.result,f.date].filter(Boolean).join(' · ')}</div><div className="feedback-links">{link&&<button onClick={()=>openNote(f.noteId,f.id)}>查看原评论</button>}<button onClick={()=>deleteFeedback(f.id)}>删除</button></div></div></div>;
 const mediaStrip=(e:Evidence)=>e.images?.length?<Carousel className="comment-media" contentClassName="comment-media-row" ariaLabel="评论配图">{e.images.map((src,i)=><div className="comment-photo" key={src}><ContentImage src={src} alt={`${e.author}的配图 ${i+1}`} variant="preview" loading="lazy"/></div>)}</Carousel>:null;
 const comment=(e:Evidence,reply=false)=><div key={e.id} className={'comment real-comment '+(reply?'nested-comment ':'')+(highlight===e.id?'highlight-comment':'')} data-anchor={e.id}><Avatar name={e.author} small={reply}/><div><div className="comment-name"><span>{e.author} {e.author===current.author&&<span className="tiny-tag">作者</span>} {e.ai&&<span className="tiny-tag">AI</span>}</span><span className="comment-likes"><HeartIcon/>{e.likes==='赞'?'':e.likes}</span></div><p>{e.text||'分享了图片'}</p>{mediaStrip(e)}<div className="comment-meta">{[e.date,e.location].filter(Boolean).join(' · ')}</div></div></div>;
 const noteTile=(n:Note)=><article className="note-tile" key={n.id}><button className="tile-main" onClick={()=>openNote(n.id)}><ContentImage className={'tile-cover '+(n.id==='beauty_02'?'cover-1':'')} src={n.images[0]} alt={n.title} variant="preview" loading="eager"/><h3>{n.title}</h3></button>{mounted(n.id)&&<button className="tile-task" onClick={()=>openTask(n.id)}><ReaderIcon/>看作业 · {getCard(n.id).candidates.length} 个方案<ChevronRightIcon/></button>}<div className="tile-meta"><Avatar name={n.author} small/><span>{n.author}</span><HeartIcon/>{n.metrics.likes}</div></article>;
 const homeNotes=['cooking_01','beauty_01','citywalk_01','cleaning_01','beauty_02','cooking_02','cleaning_02','citywalk_02'].map(getNote);
 const homeTile=(n:Note)=><article className="home-note" key={n.id}>
  <button className="home-note-main" aria-label={'查看笔记：'+n.title} onClick={()=>openNote(n.id)}><ContentImage className={'home-cover tile-cover '+(n.id==='beauty_02'?'home-cover-square':'')} src={n.images[0]} alt={n.title} variant="preview" loading={homeNotes.indexOf(n)<2?'eager':'lazy'}/><h3>{n.title}</h3></button>
  <div className="home-note-meta"><Avatar name={n.author} small/><span className="home-note-author">{n.author}</span><button className={'home-note-like '+(saved.liked.includes(n.id)?'liked':'')} aria-label={(saved.liked.includes(n.id)?'取消点赞：':'点赞：')+n.title} aria-pressed={saved.liked.includes(n.id)} onClick={()=>toggle('liked',n.id)}>{saved.liked.includes(n.id)?<HeartFilledIcon/>:<HeartIcon/>}<span>{displayCount(n.metrics.likes,saved.liked.includes(n.id)?1:0)}</span></button></div>
 </article>;
 const home=()=> <>
  <header className="topbar home-topbar"><button className="home-diandian" aria-label="点点" onClick={openChat}><img src={AS+'diandian.svg'} alt=""/></button><nav className="home-top-tabs" aria-label="首页频道"><button disabled>关注</button><button className="active" aria-current="page">发现</button><button disabled>上海</button></nav><Icon label="搜索" onClick={beginSearch}><MagnifyingGlassIcon/></Icon></header>
  <MobileScroll className="screen home-screen"><div className="home-feed">{[0,1].map(column=><div className="home-feed-column" key={column}>{homeNotes.filter((_,i)=>i%2===column).map(homeTile)}</div>)}</div><div className="end-note">— 没有更多了 —</div></MobileScroll>
  <nav className="home-bottom-nav" aria-label="底部导航" style={{bottom:native?0:bottomInset}}><button className="active" aria-current="page" onClick={()=>{rootRef.current?.querySelector('.home-screen .mobile-scroll')?.scrollTo({top:0,behavior:'smooth'})}}>首页</button><button disabled>市集</button><button className="home-publish" disabled aria-label="发布笔记"><PlusIcon/></button><button disabled>消息</button><button disabled>我</button></nav>
 </>;
 const summary=()=> scene&&scene.id!=='beauty'?<button className="ai-summary summary-folded" aria-label="展开 AI 总结" onClick={()=>go('ai')}><span className="summary-fold-body"><span className="summary-prose">{scene.intro}<strong className="mint-highlight">{scene.highlight}</strong></span><span className="summary-subhead"><ReaderIcon/>{scene.heading}</span><span className="summary-prose"><UserMentions text={scene.lead.text} refs={scene.lead.refs}/></span><span className="summary-prose summary-preview-tail">{scene.takeaways[2]}</span></span><span className="summary-fold-footer"><span>ai 参考 2 篇笔记及评论生成</span><span className="mini-avatars">{sceneNotes.map(n=><Avatar key={n.id} name={n.author} small/>)}</span><ChevronRightIcon/></span></button>: <button className="ai-summary summary-folded" aria-label="展开眼影 AI 总结" onClick={()=>go('ai')}>
  <span className="summary-fold-body">
   <span className="summary-prose">如果你在选第一盘眼影，可以先按喜欢的妆效缩小范围。<strong className="mint-highlight">偏爱日常粉色，先看裸砂粉；喜欢粉紫闪片，再对照芋泥盘。</strong></span>
   <span className="summary-subhead"><ColorWheelIcon/>配色：先从你喜欢的妆效选</span>
   <span className="summary-prose">如果你偏爱中性粉色、不喜欢橘调或大地色，可以先比较这两盘。<UserName name="少冰五分糖"/>的笔记中，有相近偏好的求购条件和使用分享，选之前留意<strong>紫调、闪片和显色</strong>的差别。</span>
   <span className="summary-prose summary-preview-tail">如果你更想看花知晓，可以按具体配色对照；很在意闪片或显肿问题的话，先核对不同体验。</span>
  </span>
  <span className="summary-fold-footer"><span>ai 参考 2 篇笔记及评论生成</span><span className="mini-avatars">{sceneNotes.map(n=><Avatar key={n.id} name={n.author} small/>)}</span><ChevronRightIcon/></span>
 </button>;
 const inlineRefs=(ids:string[],label='查看依据')=><button className="ai-evidence" onClick={()=>showSources(ids)}>{label}<ChevronRightIcon/></button>;
 const aiTask=(id:string,item?:string)=>mounted(id)?<button className="ai-task-embed" aria-label={item?`查看${getCard(id).candidates.find(c=>c.id===item)?.name}的作业`:`打开作业：${titleFor(id)}`} onClick={()=>openTask(id,item)}>
  <span className="ai-task-top"><ReaderIcon/><span>笔记里的作业</span><span className="ai-task-author">{getNote(id).author}</span></span>
  <strong>{titleFor(id)}</strong><span className="ai-task-description">{!id.startsWith('beauty')?taskExtras[id].intro:id==='beauty_01'?'对照粉色、闪片和搭配条件，找到适合自己的方案。':'按原帖图片对照配色，把作者和评论里的体验一起看。'}</span>
  <span className="ai-task-bottom"><span>{item?'已定位到 '+getCard(id).candidates.find(c=>c.id===item)?.name:`${getCard(id).candidates.length} 个方案 · 各有依据`}</span><b>{lastTried(id)?'继续看作业':'看作业'}<ChevronRightIcon/></b></span>
 </button>:null;
 const aiCandidate=(item:AiCandidate)=>{
  const pictures=(item.imageRefs||[]).flatMap(id=>{const e=sources[id];return (e.image?[e.image]:e.images||[]).slice(0,3).map(url=>({url,id}))});
  return <section className="ai-product" key={item.id}>
   <div className="ai-product-heading"><button className="ai-product-name" onClick={()=>openTask(item.noteId,item.id)}>{item.name}<MagnifyingGlassIcon/></button>{inlineRefs(item.refs,item.disputed?'体验有分歧':'查看依据')}</div>
   <p><UserMentions text={item.text} refs={item.refs}/></p>
   {pictures.length>0&&<Carousel className="ai-photo-rail" contentClassName={'ai-photo-row '+(pictures.length===1?'single-photo':'')} ariaLabel={item.name+'的原帖配图'}>{pictures.map((pic,i)=><div className="ai-photo" key={pic.url}><ContentImage src={pic.url} alt={item.name+'的原帖配图 '+(i+1)} variant="preview" loading="lazy"/></div>)}</Carousel>}
  </section>;
 };
 const renderAnswer=(answerQuery:string)=>{const scene=sceneForQuery(answerQuery),sceneNotes=notes.filter(n=>scene?.noteIds.includes(n.id));const summarySaved=savedSummaries.includes(scene?.id||'');const disliked=!!dislikedQueries[answerQuery];if(!scene)return <article className="answer"><p>可以和我聊聊眼影怎么选、腊肠焖饭怎么做、白鞋洗后发黄，或上海半天怎么逛。你想先了解哪一个？</p></article>;return <article className="answer main-answer" data-answer-query={answerQuery}>
     {scene&&scene.id!=='beauty'?<><p>{scene.intro}<strong className="mint-highlight">{scene.highlight}</strong></p><section className="ai-editorial-section"><h2><ReaderIcon/>{scene.heading}</h2><p><UserMentions text={scene.lead.text} refs={scene.lead.refs}/>{inlineRefs(scene.lead.refs)}</p></section>{sceneNotes.map(n=><section className="ai-editorial-section" key={n.id}><h2>{titleFor(n.id)}</h2>{getCard(n.id).candidates.map(item=>aiCandidate({noteId:n.id,id:item.id,name:item.name,text:item.intro||'',refs:sections.flatMap(s=>(item[s.key]||[]).flatMap(f=>f.refs)),imageRefs:item.image?[Object.values(sources).find(e=>e.image===item.image)!.id]:[]}))}{aiTask(n.id)}</section>)}<section className="ai-takeaways"><h2><MagicWandIcon/>{scene.id==='citywalk'?'出发前，再核对一下':'照做前，再核对一下'}</h2><ul>{scene.takeaways.map(t=><li key={t}>{t}</li>)}</ul></section></>:<>
     <p>如果你在选第一盘眼影，可以先按喜欢的妆效缩小范围。<strong className="mint-highlight">偏爱日常粉色，先看裸砂粉；喜欢粉紫闪片，再对照芋泥盘。</strong></p>
     <section className="ai-editorial-section"><h2><ColorWheelIcon/>配色：先从你喜欢的妆效选</h2>
      <p>如果你偏爱中性粉色、不喜欢橘调或大地色，可以先比较<strong className="mint-highlight">裸砂粉和芋泥盘</strong>。<UserName name="少冰五分糖"/>的笔记中，提问者有相近偏好，评论里也有这两盘的使用分享。{inlineRefs(['beauty_01:body:001',commentRef(1,132),commentRef(1,19)])}</p>
      <ul><li><strong>偏爱日常粉色：</strong>可以先看裸砂粉的使用反馈；如果不喜欢紫调，要留意推荐者后续的补充。{inlineRefs([commentRef(1,132),commentRef(1,135)])}</li><li><strong>想一盘兼顾多种用途：</strong>如果你也希望有闪片、眼线色和卧蚕色，可以沿用这篇笔记的比较方向，到作业里逐项核对哪些有明确依据。{inlineRefs(['beauty_01:body:002'])}</li></ul>
     </section>
     <section className="ai-editorial-section"><h2><MagicWandIcon/>闪片：先看是不是你想要的质感</h2>
      <p>如果你喜欢粉紫色又想要闪片，可以考虑芋泥盘，但建议先看试色。<UserName name="少冰五分糖"/>的笔记中，有人分享了<strong className="mint-highlight">先搓细、再上眼</strong>的用法，也有人对闪片不满意。{inlineRefs([19,69,82,84].map(id=>commentRef(1,id)))}</p>
      <p>如果你主要用哑光、也接受单独配闪色，深棕哑光可以作为另一个方向。这篇笔记中有回购分享，也有人明确提醒它缺细闪。{inlineRefs([commentRef(1,10),commentRef(1,11)])}</p>
     </section>
     <section className="ai-editorial-section"><h2><MixIcon/>3CE，先把这几个方向放在一起看</h2><p>按你更在意的配色和妆效，先看这几个方向。具体推荐都附上了笔记中的依据，也保留了需要留意的条件。</p>{aiCandidates.filter(c=>c.noteId==='beauty_01').map(aiCandidate)}
      <p className="task-bridge">还在纠结怎么取舍？打开这篇笔记的作业，把候选、使用条件和分歧逐项对照，找到适合自己的方案。</p>{aiTask('beauty_01')}
     </section>
     <section className="ai-editorial-section"><h2><ColorWheelIcon/>想选花知晓，可以这样缩小范围</h2>
      <p>如果你更想选花知晓，可以先按<strong className="mint-highlight">配色利用率、闪片质感和是否显肿</strong>来比较。下面结合 <UserName name="LVnook"/> 的黄二白配色测评和评论，帮你看清各自适合先核对什么。{inlineRefs(['beauty_02:title','beauty_02:body:001'])}</p>
      {aiCandidates.filter(c=>c.noteId==='beauty_02').map(aiCandidate)}
      <p className="task-bridge">想继续比较其他盘？这份作业按原帖图序整理了 15 个候选，有补充体验的地方也放在一起。</p>{aiTask('beauty_02')}
     </section>
     <section className="ai-takeaways"><h2><MagicWandIcon/>选之前，记住这三件事</h2><ul><li><strong>偏爱什么，就先看什么：</strong>想要日常粉色，先看裸砂粉；喜欢粉紫闪片，再对照芋泥盘。</li><li><strong>介意什么，就重点核对什么：</strong>很在意闪片或显肿，就先看原图和不同体验，别只看一句推荐。</li><li><strong>把经验留在作业里：</strong>参考或试过可以标记“抄了”，也可以回来补充实际体验。</li></ul></section>
     </>}<button className="ai-source-footer" onClick={()=>showSources(scene?.id==='beauty'?answerRefs:sceneNotes.flatMap(n=>allRefs(n.id)))}><span className="mini-avatars">{sceneNotes.map(n=><Avatar key={n.id} name={n.author} small/>)}</span>参考 2 篇笔记及评论<ChevronRightIcon/></button>
     <div className="ai-answer-actions"><Icon label="复制总结" onClick={()=>copyAnswer(answerQuery)}><CopyIcon/></Icon><Icon label={summarySaved?'取消收藏总结':'收藏总结'} onClick={()=>{setSaved(s=>({...s,savedSummaries:summarySaved?savedSummaries.filter(id=>id!==scene?.id):[...savedSummaries,scene!.id]}));setToast(summarySaved?'已取消收藏总结':'已收藏总结')}}>{summarySaved?<StarFilledIcon/>:<StarIcon/>}</Icon><Icon label="分享总结" onClick={()=>shareAnswer(answerQuery)}><Share1Icon/></Icon><span/><Icon label={disliked?'取消不感兴趣':'不感兴趣'} onClick={()=>{setDislikedQueries(v=>({...v,[answerQuery]:!v[answerQuery]}));setToast(disliked?'已取消反馈':'已记录你的反馈')}}><MinusCircledIcon/></Icon><Icon label="回到总结开头" onClick={()=>{const el=Array.from(rootRef.current?.querySelectorAll<HTMLElement>('.main-answer')||[]).find(el=>el.dataset.answerQuery===answerQuery);const scroll=el?.closest('.mobile-scroll');if(scroll&&el)scroll.scrollTo({top:scroll.scrollTop+el.getBoundingClientRect().top-scroll.getBoundingClientRect().top-12,behavior:'smooth'})}}><ResetIcon/></Icon></div>
    </article>;};
 const renderFollowups=(turns:Followup[])=>turns.map((f,i)=><section className="followup-turn" key={i}><div className="query-bubble">{f.question}</div><div className="answer followup-answer"><p><UserMentions text={f.answer} refs={f.refs}/></p>{f.refs.length>0&&inlineRefs(f.refs)}{f.noteId&&aiTask(f.noteId,f.candidateId)}</div></section>);
 const chatComposer=()=> <footer className="ai-composer composer-disabled" style={{bottom:native?0:bottomInset}}><form onSubmit={e=>e.preventDefault()}><button type="button" disabled aria-label="语音输入"><SpeakerLoudIcon/></button><KeyboardInput disabled aria-label={page==='chat'?'发消息给点点':'继续追问'} placeholder="发消息或按住说话…" value=""/><button type="button" disabled aria-label="添加图片"><CameraIcon/></button><button type="button" disabled aria-label="更多输入方式"><PlusCircledIcon/></button></form><small>内容由 AI 生成</small></footer>;
 const chattedTopics=new Set(chats.map(c=>sceneForQuery(c.query)?.id));
 const chatPrompts=[...queries.filter(q=>!chattedTopics.has(sceneForQuery(q)?.id)),...(sceneForQuery(chats.at(-1)?.query||'')?.followups||['偏爱日常粉色','想要好看的闪片','想看花知晓'])].filter(q=>!chats.some(c=>c.query===q||c.followups.some(f=>f.question===q))).slice(0,3);
 const chatPage=()=> <><header className="topbar chat-topbar"><Icon label="关闭点点" onClick={()=>go('home')}><Cross2Icon/></Icon><div className="chat-title"><img className="diandian" src={AS+'diandian.svg'} alt=""/><b>点点</b></div><Icon label="更多" disabled onClick={()=>open('menu')}><DotsHorizontalIcon/></Icon></header><MobileScroll className={'screen ai-screen chat-screen '+(!chats.length?'chat-empty':'')}>{chats.map(chat=><section className="chat-session" data-chat-query={chat.query} key={chat.query}><div className="query-bubble">{chat.query}</div>{renderAnswer(chat.query)}{renderFollowups(chat.followups)}</section>)}<section className="chat-guide">{chats.length>0&&<div className="chat-new-topic">聊聊新话题</div>}<div className="chat-greeting">{chats.length?'哈喽，再度相逢！心里有什么疑惑或者想唠的内容，都尽管说出来。':'嗨，我是点点。想找灵感，还是有个问题想弄明白？我们聊聊吧。'}</div><div className="chat-suggestions">{chatPrompts.map(q=><button key={q} onClick={()=>askChat(q)}>{q}</button>)}</div></section></MobileScroll>{chatComposer()}</>;
 const aiDetail=()=> <>
  <MobileScroll className="screen ai-screen"><div className="query-bubble">{query}</div>
   {!relevant?<div className="empty-state"><h2>暂时没有找到相关笔记</h2><button className="pill-button" onClick={()=>search(queries[0])}>看看眼影怎么选</button></div>:<>
    {renderAnswer(query)}
    <section className="ai-refine"><h2><ChatBubbleIcon/>帮你再缩小一点范围</h2><p>你更在意什么？</p><div className="refine-choices">{(scene?.id==='beauty'?['偏爱日常粉色','想要好看的闪片','想看花知晓']:scene?.followups||[]).map(q=><button key={q} onClick={()=>askFollowup(q)}>{q}</button>)}</div><small>{scene?.id==='beauty'?'也可以告诉我你的肤色、眼型或在意的妆效。':scene?.id==='cooking'?'也可以说说家里有什么食材。':scene?.id==='cleaning'?'也可以补充鞋面材质、洗法和晾法。':'也可以说说想看的风景和出行方式。'}</small></section>
    {followups.map((f,i)=><section className="followup-turn" key={i}><div className="query-bubble">{f.question}</div><div className="answer followup-answer"><p><UserMentions text={f.answer} refs={f.refs}/></p>{f.refs.length>0&&inlineRefs(f.refs)}{f.noteId&&aiTask(f.noteId,f.candidateId)}</div></section>)}
   </>}
  </MobileScroll>
  <button className="ai-jump-bottom" aria-label="跳到追问区" style={{bottom:(native?0:bottomInset)+84}} onClick={()=>scrollAi(true)}><ArrowDownIcon/></button>
  {chatComposer()}
 </>;
 const candidateDetails=(item:Candidate)=><article className="plan-panel" role="tabpanel" id={'plan-panel-'+item.id} aria-labelledby={'plan-tab-'+item.id} data-candidate={item.id}>
  <div className="plan-heading"><div><small>{taskId.startsWith('beauty')?'选购方案':taskId.startsWith('citywalk')?'出行方案':'作业方案'} · {planLabel(taskId,item)}</small><h2>{item.name}</h2></div>{saved.tried.includes(taskId+':'+item.id)&&<span className="plan-saved"><CheckIcon/>已抄</span>}</div>
  <p className="plan-lead"><UserMentions text={planIntro(taskId,item)} refs={[...(item.nameRefs||[]),...sections.flatMap(s=>(item[s.key]||[]).flatMap(f=>f.refs))]}/></p>
  {visibleUpdates(taskId).filter(u=>u.candidateId===item.id).map(u=><div key={u.id} className="plan-update"><b>{u.title}</b><p><UserMentions text={u.text} refs={u.refs}/></p><small>{u.updatedAt}</small>{refs(u.refs)}</div>)}
  {item.image&&<div className="candidate-image"><ContentImage src={item.image} alt={item.name}/></div>}
  {item.id==='taro'&&mediaStrip(sources[commentRef(1,84)])}
  {item.nameRefs&&<div className="name-source">名称来自作者回复 {refs(item.nameRefs)}</div>}
  {sectionsFor(taskId).filter(s=>s.key!=='differences').map(s=>item[s.key]?.length?<section key={s.key} className={'candidate-section section-'+s.key}><h4>{s.key==='basis'?'参考体验':s.label}</h4>{factList(item[s.key]!)}</section>:null)}
  {!!item.differences?.length&&<section className="candidate-section section-differences"><h4>也有人有不同体验</h4>{factList(item.differences)}</section>}
  <div className="practice-action"><button className={'copy-task-button '+(saved.tried.includes(choiceKey)?'is-copied':'')} aria-pressed={saved.tried.includes(choiceKey)} aria-label={saved.tried.includes(choiceKey)?'取消抄了':'抄了'} onClick={()=>{toggle('tried',choiceKey);setToast(saved.tried.includes(choiceKey)?'已取消「抄了」':'已标记「抄了」')}}>{saved.tried.includes(choiceKey)?<CheckIcon/>:<ReaderIcon/>}<span>{saved.tried.includes(choiceKey)?'已抄':'抄了'}</span>{saved.tried.includes(choiceKey)&&<small>取消</small>}</button></div>
  {feedbackFor(taskId,item.id).length>0&&<div className="practice-feedback"><h3>实际用过的人怎么说</h3>{feedbackFor(taskId,item.id).map(f=>feedback(f,true))}</div>}
  <button className="share-practice" onClick={startFeedback}><Pencil1Icon/>分享这个方案的使用体验<ChevronRightIcon/></button>
 </article>;
 const questionScopeLabel=(q:TaskQuestion|LocalQuestion)=>{const ids=('candidateIds' in q?q.candidateIds:undefined)||(q.candidateId?[q.candidateId]:[]);return orderedPlans(taskId).filter(c=>ids.includes(c.id)).map(c=>planLabel(taskId,c)).join('、')||'整份作业'};
 const questionList=()=> <section className="task-public task-questions"><div className="public-heading"><h3><ChatBubbleIcon/>问一问</h3><button onClick={startQuestion}>我要提问<ChevronRightIcon/></button></div>
  {questions.map(q=><article className="question-row" key={q.id}><button className="question-title" onClick={()=>showQuestion(q.id)}><span className="qa-badge">问</span><b>{q.title}</b><ChevronRightIcon/></button><div className="question-meta"><span>{questionScopeLabel(q)} · {'questionRef' in q?'来自笔记评论':'我的提问'}</span></div><button className="question-preview" onClick={()=>showQuestion(q.id)}>{'answerRefs' in q?<><span className="qa-answer-label">答</span><span>{sources[q.answerRefs.at(-1)!].text.replace(/^回复.*?[:：]\s*/, '')}</span></>:<span>{saved.answers.some(a=>a.questionId===q.id)?saved.answers.filter(a=>a.questionId===q.id).at(-1)!.text:'还没有回答，等一个用过的人分享'}</span>}</button><div className="question-actions"><button onClick={()=>alsoAsk(q.id)} className={saved.alsoAsked.includes(q.id)?'is-following':''}>{saved.alsoAsked.includes(q.id)?<CheckIcon/>:<PlusCircledIcon/>}{saved.alsoAsked.includes(q.id)?'已关注这个问题':'我也想问'}</button><button onClick={()=>showQuestion(q.id)}>查看与回答<ChevronRightIcon/></button></div></article>)}
 </section>;
 const questionDetail=()=>activeQuestion&&<div className="question-detail"><button className="back-to-task" onClick={()=>open('task')}><ArrowLeftIcon/>返回作业</button><small className="question-scope">{questionScopeLabel(activeQuestion)}</small><h2>{activeQuestion.title}</h2>
  {'questionRef' in activeQuestion?<div className="question-original"><p>{sources[activeQuestion.questionRef].text}</p>{mediaStrip(sources[activeQuestion.questionRef])}<small>{sources[activeQuestion.questionRef].author} · 来自笔记评论</small>{refs([activeQuestion.questionRef])}</div>:<div className="question-owner"><span>我 · {activeQuestion.date}</span><button onClick={()=>deleteQuestion(activeQuestion.id)}>删除提问</button></div>}
  <button className="also-ask" onClick={()=>alsoAsk(activeQuestion.id)}>{saved.alsoAsked.includes(activeQuestion.id)?<CheckIcon/>:<PlusCircledIcon/>}{saved.alsoAsked.includes(activeQuestion.id)?'已关注这个问题':'我也想问'}</button>
  <h3 className="qa-replies-heading">大家的回答</h3>
  {'answerRefs' in activeQuestion&&activeQuestion.answerRefs.map(id=>{const a=sources[id];return <article className="qa-reply" key={id}><div><Avatar name={a.author} small/><b>{a.author}</b>{a.author===taskNote.author&&<span className="tiny-tag">笔记作者</span>}</div><p>{a.text.replace(/^回复.*?[:：]\s*/, '')}</p><small>{a.date} · 来自笔记评论</small>{refs([id])}</article>})}
  {saved.answers.filter(a=>a.questionId===activeQuestion.id).map(a=><article className="qa-reply" key={a.id}><div><Avatar name="我" small/><b>我</b></div><p>{a.text}</p><small>{a.date}</small><button className="withdraw-answer" onClick={()=>{setSaved(s=>({...s,answers:s.answers.filter(v=>v.id!==a.id)}));setToast('回答已删除')}}>删除回答</button></article>)}
  {!('answerRefs' in activeQuestion)&&!saved.answers.some(a=>a.questionId===activeQuestion.id)&&<p className="qa-empty">还没有回答。实际用过的话，欢迎说说你的经验。</p>}
  <form className="question-form reply-form" onSubmit={e=>{e.preventDefault();publishAnswer()}}><label>我来回答<KeyboardTextarea aria-label="填写回答" value={replyDraft} onChange={e=>setReplyDraft(e.target.value)} onBlur={()=>keyboard.hide()} maxLength={1000}/></label><button type="submit" className="primary-button" onPointerDown={e=>e.preventDefault()} disabled={!replyDraft.trim()}>发布回答</button></form>
 </div>;
 return <div className={'xhs-app '+(page==='ai'||page==='chat'?'ai-view':page==='home'?'home-view':page==='search'?'search-view':'')} ref={rootRef}>
  {page==='home'?home():page==='chat'?chatPage():page==='search'?<header className="topbar search-entry-topbar"><Icon label="返回" onClick={()=>go('home')}><ChevronLeftIcon/></Icon><div className="search-entry-field"><KeyboardTextarea aria-label="搜索小红书" disabled value="" placeholder={"受内容接口限制\n请点击下方推荐query进行搜索"} rows={2}/><button disabled className="search-submit">搜索</button></div></header>:<header className="topbar"><Icon label="返回" onClick={()=>go(page==='note'?origin:page==='results'?'search':'results')}><ArrowLeftIcon/></Icon>{page==='note'?<><Avatar name={current.author}/><span className="note-author">{current.author}</span><button className={'follow-button '+(saved.followed.includes(noteId)?'followed':'')} onClick={()=>toggle('followed',noteId)}>{saved.followed.includes(noteId)?'已关注':'关注'}</button><Icon label="更多" disabled onClick={()=>open('menu')}><DotsHorizontalIcon/></Icon></>:page==='ai'?<><img className="diandian" src={AS+'diandian.svg'} alt=""/><b className="top-title">点点</b><Icon label="更多" disabled onClick={()=>open('menu')}><DotsHorizontalIcon/></Icon></>:<><form className="searchbar" onSubmit={e=>{e.preventDefault();search(input)}}><KeyboardInput aria-label="搜索小红书" value={input} onChange={e=>setInput(e.target.value)} onFocus={beginSearch} onBlur={()=>keyboard.hide()} enterKeyHint="search"/><button type="button" className="clear-input" aria-label="返回搜索输入页" onClick={beginSearch}><Cross2Icon/></button><button className="search-submit">搜索</button></form><Icon label="更多" disabled onClick={()=>open('menu')}><DotsHorizontalIcon/></Icon></>}</header>}
  {page==='search'&&<><MobileScroll className="screen search-entry-screen"><div className="search-entry-tools"><button disabled><CircleIcon/>问ai</button><span aria-hidden="true"/><button disabled><CameraIcon/>拍照搜</button></div><section className="search-recommendations"><div className="search-recommendations-heading"><h2>猜你想搜</h2><button disabled aria-label="更多推荐"><DotsHorizontalIcon/></button></div><div className="search-query-grid">{queries.map(q=><button key={q} onClick={()=>search(q)}>{q}</button>)}</div></section></MobileScroll><footer className="search-voice" style={{bottom:native?0:bottomInset}}><p>按住提问 有问必答<span aria-hidden="true">✨</span></p><button disabled aria-label="语音输入"><img src={AS+'search-mic.svg'} alt=""/></button></footer></>}
  {page==='results'&&<><nav className="result-tabs">{['全部','用户','商品','图片','视频'].map(t=><button key={t} className={tab===t?'active':''} disabled={t!=='全部'} onClick={()=>setTab(t)}>{t}</button>)}<button className="ask-tab" onClick={()=>go('ai')}><img className="diandian" src={AS+'diandian.svg'} alt=""/>问点点</button></nav><MobileScroll className="screen results-screen" key={query+tab}>{tab==='全部'&&relevant&&summary()}{(tab==='全部'||tab==='图片')&&<><Carousel className="filter-carousel" contentClassName="filter-row" ariaLabel="筛选笔记">{(scene?.filters||['综合']).map(f=><button key={f} className={filter===f?'selected':''} onClick={()=>setFilter(f)}>{f}</button>)}</Carousel><div className="note-grid">{results.map(noteTile)}</div>{results.length===0&&<div className="empty-state"><MagnifyingGlassIcon/><h2>暂时没有相关笔记</h2><p>试试眼影、焖饭、白鞋或上海半日游</p></div>}</>}{tab==='用户'&&results.map(n=><button className="user-result" key={n.id} onClick={()=>openNote(n.id)}><Avatar name={n.author}/><span>{n.author}<small>{n.title}</small></span><ChevronRightIcon/></button>)}{(tab==='商品'||tab==='视频')&&<div className="empty-state"><MagnifyingGlassIcon/><h2>暂无相关{tab}</h2><button className="pill-button" onClick={()=>setTab('全部')}>看看笔记</button></div>}<div className="end-note">— 没有更多了 —</div></MobileScroll></>}
  {page==='note'&&<><MobileScroll className="screen note-screen" key={noteId}><div data-anchor="note-start"/><Carousel className="note-gallery" contentClassName="note-gallery-row" ariaLabel="笔记图片">{current.images.map((src,i)=><div key={src} className="gallery-image" data-anchor={`${noteId}:media:${String(i+1).padStart(3,'0')}`}><ContentImage src={src} alt={`原帖图 ${i+1}`} loading={i?'lazy':'eager'}/><span>{i+1}/{current.images.length}</span></div>)}</Carousel><div className="note-body"><h1 data-anchor={`${noteId}:title`}>{current.title}</h1>{current.body.map(b=><p key={b.id} className={b.tags?'hashtags':''} data-anchor={b.id}>{b.text}</p>)}<div className="note-date">{current.date}</div>{preview(noteId)}{authorMode&&<button className="inline-author-tools" onClick={()=>{setTaskId(noteId);setDraft(titleFor(noteId));open('creator')}}>管理这份作业</button>}</div><div className="comments" data-anchor="comments"><div className="comments-heading">共 {displayCount(current.metrics.comments,feedbackFor(noteId).length)} 条评论</div>{feedbackFor(noteId).map(f=>feedback(f))}{current.comments.filter(c=>!c.parent).map(c=>{const replies=current.comments.filter(r=>r.parent===c.id),visible=Math.min(expanded[c.id]||0,replies.length),remaining=replies.length-visible;return <div className="comment-thread" key={c.id}>{comment(c)}{replies.length>0&&<div className="reply-thread">{replies.slice(0,visible).map(r=>comment(r,true))}<div className="reply-controls">{remaining>0&&<button className="expand-replies" onClick={()=>setExpanded(v=>({...v,[c.id]:Math.min((v[c.id]||0)+5,replies.length)}))}>展开 {Math.min(5,remaining)} 条回复<ChevronRightIcon/></button>}{visible>0&&<button className="expand-replies collapse-replies" onClick={()=>setExpanded(v=>({...v,[c.id]:0}))}>收起回复</button>}</div></div>}</div>})}<div className="comments-end">— 暂无更多评论 —</div></div></MobileScroll><footer className="note-footer" style={{bottom:native?0:bottomInset}}><button className="comment-placeholder" disabled><Pencil1Icon/>说点什么...</button><button className={saved.liked.includes(noteId)?'liked':''} aria-label="点赞笔记" onClick={()=>toggle('liked',noteId)}>{saved.liked.includes(noteId)?<HeartFilledIcon/>:<HeartIcon/>}{displayCount(current.metrics.likes,saved.liked.includes(noteId)?1:0)}</button><button className={saved.collected.includes(noteId)?'collected':''} aria-label="收藏笔记" onClick={()=>{toggle('collected',noteId);setToast(saved.collected.includes(noteId)?'已取消收藏':'已收藏笔记')}}>{saved.collected.includes(noteId)?<StarFilledIcon/>:<StarIcon/>}{displayCount(current.metrics.collects,saved.collected.includes(noteId)?1:0)}</button><Icon label="查看评论" onClick={()=>setJump('comments')}><ChatBubbleIcon/></Icon></footer></>}
  {page==='ai'&&aiDetail()}
  {homeLeaving&&page==='chat'&&<div className="home-slide-away" aria-hidden="true" inert>{home()}</div>}
  <BottomSheet open={sheet!==null} onOpenChange={v=>{if(!v){keyboard.hide();setSheet(null)}}} snap={(sheet==='task') ? .9 : .82} title={sheet==='task'?titleFor(taskId):sheet==='ask'?'问问用过的人':sheet==='question'?'问一问':sheet==='sources'?'查看来源':sheet==='feedback'?'分享使用体验':sheet==='creator'?'管理作业':'更多'} description="查看作业方案、原文来源和使用反馈">
   <div className="sheet-close"><Icon label="关闭" onClick={()=>{keyboard.hide();setSheet(null)}}><Cross2Icon/></Icon></div>
   {sheet==='task'&&<div className="task-detail task-plans">
    <div className="plan-nav"><Carousel className="plan-tabs" ariaLabel="切换作业方案"><div role="tablist" aria-label="作业方案" className="plan-tab-row">{orderedPlans(taskId).map(item=><button role="tab" id={'plan-tab-'+item.id} aria-selected={selected===item.id} aria-controls={'plan-panel-'+item.id} tabIndex={selected===item.id?0:-1} key={item.id} className="plan-tab" onClick={()=>switchPlan(item.id)} onKeyDown={e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const items=orderedPlans(taskId);const index=items.findIndex(c=>c.id===item.id);const next=items[e.key==='Home'?0:e.key==='End'?items.length-1:(index+(e.key==='ArrowRight'?1:-1)+items.length)%items.length];switchPlan(next.id);requestAnimationFrame(()=>document.getElementById('plan-tab-'+next.id)?.focus())}}}>{planLabel(taskId,item)}{saved.tried.includes(taskId+':'+item.id)&&<CheckIcon/>}</button>)}</div></Carousel></div>
    {candidate&&candidateDetails(candidate)}
    {!!extras.notices?.length&&<section className="task-public task-notices"><div className="public-heading"><h3><ReaderIcon/>选之前都要留意</h3></div>{factList(extras.notices)}</section>}
    {!!extras.discussions?.length&&<section className="task-public task-discussions"><div className="public-heading"><h3><ChatBubbleIcon/>大家还在讨论</h3></div>{factList(extras.discussions)}</section>}
    {questionList()}
    {visibleUpdates(taskId).length>0&&<section className="task-public latest-updates"><div className="public-heading"><h3>最新信息</h3></div>{visibleUpdates(taskId).map(u=><article key={u.id}><b>{u.title}</b><p><UserMentions text={u.text} refs={u.refs}/></p><small>更新于 {u.updatedAt}</small>{u.candidateId&&<button onClick={()=>switchPlan(u.candidateId!)}>查看相关方案<ChevronRightIcon/></button>}{refs(u.refs)}</article>)}</section>}
    <div className="task-return-links">{(page==='ai'||page==='chat')&&<button className="return-note" onClick={()=>open(null)}><ArrowLeftIcon/>返回点点，继续看总结</button>}</div>
   </div>}
   {sheet==='ask'&&<form className="question-form" onSubmit={e=>{e.preventDefault();publishQuestion()}}><button type="button" className="back-to-task" onClick={()=>open('task')}><ArrowLeftIcon/>返回作业</button><div className="question-scope-heading"><h3 id="question-plans-label">你想问哪些方案？</h3></div><div className="question-scope-options" role="group" aria-labelledby="question-plans-label">{orderedPlans(taskId).map(item=><button key={item.id} type="button" role="checkbox" aria-checked={questionScopes.includes(item.id)} className={questionScopes.includes(item.id)?'selected':''} onClick={()=>setQuestionScopes(ids=>ids.includes(item.id)?ids.filter(id=>id!==item.id):[...ids,item.id])}><span className="scope-check" aria-hidden="true">{questionScopes.includes(item.id)&&<CheckIcon/>}</span><span>{planLabel(taskId,item)}</span></button>)}</div><label>说说你的问题<KeyboardTextarea aria-label="填写问题" value={questionDraft} onChange={e=>setQuestionDraft(e.target.value)} onBlur={()=>keyboard.hide()} maxLength={300}/></label><button type="submit" className="primary-button" onPointerDown={e=>e.preventDefault()} disabled={!questionDraft.trim()||!questionScopes.length}>发布问题</button></form>}
   {sheet==='question'&&questionDetail()}
   {sheet==='sources'&&<div className="sources-sheet">{sheetBack&&<button className="back-to-task" onClick={()=>open(sheetBack)}><ArrowLeftIcon/>返回{sheetBack==='question'?'问答':'作业'}</button>}{sourceIds.map(id=>{const e=sources[id];if(!e)return null;const parent=e.parent?sources[e.parent]:undefined;return <article className="source-card" key={id}><div className="source-user"><Avatar name={e.author} small/><b>{e.author}</b><span className="tiny-tag">{e.label}</span></div>{parent?.kind==='comment'&&<div className="source-context"><small>这条回复所在的讨论</small><p>{parent.author}：{parent.text}</p></div>}{e.text&&<p className="exact-quote">{e.text}</p>}{e.image&&<div className="source-image-button"><ContentImage src={e.image} alt={e.label}/></div>}{mediaStrip(e)}<small>{e.date}</small><button className="source-jump" onClick={()=>openNote(e.noteId,e.kind==='image'&&e.parent?e.parent:e.id)}>定位到原文<ChevronRightIcon/></button><button className="source-note-title" onClick={()=>openNote(e.noteId)}>{getNote(e.noteId).title}<ChevronRightIcon/></button></article>})}</div>}
   {sheet==='feedback'&&candidate&&<form className="feedback-form" onSubmit={e=>{e.preventDefault();publish()}}><button type="button" className="back-to-task" onClick={()=>open('task')}><ArrowLeftIcon/>返回作业</button><div className="linked-branch"><ReaderIcon/><span>{titleFor(taskId)}<br/><b>{candidate.name}</b></span></div><label className="feedback-label">个人情况<KeyboardInput aria-label="个人情况" value={skin} onChange={e=>setSkin(e.target.value)} onBlur={()=>keyboard.hide()} placeholder="选填" maxLength={60}/></label><div className="outcome-row">{['适合我','有调整','不太适合'].map(o=><button type="button" key={o} className={outcome===o?'chosen':''} onClick={()=>setOutcome(o)}>{o}</button>)}</div><KeyboardTextarea aria-label="抄作业的心得" placeholder="说说抄作业的心得" value={text} onChange={e=>setText(e.target.value)} onBlur={()=>keyboard.hide()} maxLength={1000}/><FeedbackPhotoPicker photos={feedbackPhotos} onChange={setFeedbackPhotos} onBusy={setPhotosBusy} beforePick={()=>keyboard.hide()} disabled={publishing}/><button type="submit" className="primary-button" onPointerDown={e=>e.preventDefault()} disabled={!text.trim()||photosBusy||publishing}>{publishing?'发布中…':'发布体验'}</button></form>}
   {sheet==='menu'&&<div className="demo-menu"><p>我抄过的作业</p>{savedSummaries.map(id=><button key={id} className="wide-choice" onClick={()=>{const q=sceneForId(id).query;setQuery(q);setInput(q);setFollowups([]);pagePositions.current.ai=0;go('ai',q)}}>{sceneForId(id).query}<ChevronRightIcon/></button>)}{triedPlans.map(item=><button className="wide-choice" key={item.noteId+item.id} onClick={()=>openTask(item.noteId,item.id)}><span>{item.name}</span><ChevronRightIcon/></button>)}{!triedPlans.length&&<p className="menu-empty">还没有标记「抄了」的作业</p>}<h3 className="section-label">收藏的笔记</h3>{notes.filter(n=>saved.collected.includes(n.id)).map(n=><button className="wide-choice" key={n.id} onClick={()=>openNote(n.id)}>{n.title}<ChevronRightIcon/></button>)}{!saved.collected.length&&<p className="menu-empty">还没有收藏笔记</p>}{page==='note'&&<a className="source-external" href={current.url} target="_blank" rel="noreferrer"><ExternalLinkIcon/>在小红书打开原笔记</a>}{authorMode&&<button className="wide-choice" onClick={()=>{setTaskId(noteId);setDraft(titleFor(noteId));open('creator')}}>管理作业<ChevronRightIcon/></button>}{toolsMode&&<button className="wide-choice danger" onClick={()=>{setSaved(initial);setToast('本地记录已重置');open(null)}}>重置本地记录</button>}</div>}
   {sheet==='creator'&&<div className="creator-sheet"><div className="task-attribution"><Avatar name={taskNote.author}/>{taskNote.author}</div><label className="field-label">作业标题<KeyboardInput aria-label="作业标题" value={draft} onChange={e=>setDraft(e.target.value)} onBlur={()=>keyboard.hide()} maxLength={28}/></label><div className="creator-review"><h3>内容与来源</h3><p>{card.candidates.length} 个候选；每条评价可返回原文核对。</p><button className="source-jump" onClick={()=>showSources(allRefs(taskId))}>查看引用<ChevronRightIcon/></button></div><button className="primary-button" disabled={!draft.trim()} onClick={()=>{setSaved(s=>({...s,titles:{...s.titles,[taskId]:draft.trim()},mounted:{...s.mounted,[taskId]:true}}));open('task');setToast('已更新笔记中的作业')}}>保存并展示</button>{mounted(taskId)&&<button className="return-note danger" onClick={()=>{setSaved(s=>({...s,mounted:{...s.mounted,[taskId]:false}}));open(null);setToast('已从笔记移除作业')}}>从笔记移除</button>}</div>}
  </BottomSheet>{toast&&<div className="toast" role="status" style={{bottom:Math.max(110,bottomInset+20)}}>{toast}</div>}
 </div>;
}
